check.fn:
(t, h) => {
  const out = [];
  const groups = new Map();
  for (const e of (t && t.effects) || []) {
    if (!e || !e.key) continue;
    const a = e.args ? JSON.stringify(e.args) : '';
    const g = [e.instance, e.system, e.op, a].join('|');
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(e);
  }
  for (const list of groups.values()) {
    if (list.length < 2) continue;
    const first = list[0];
    for (const e of list.slice(1)) {
      const ok = e.key === first.key;
      out.push({
        subject: e.subject ?? null,
        at: e.at,
        ok: ok,
        why: ok ? 'repeated effect reuses the same idempotency key' : 'repeated effect used a different idempotency key',
        refs: [first.id, e.id]
      });
    }
  }
  return out;
}

(t, h) => {
  const cands = [];
  for (const e of t.effects || []) {
    if (e.key != null) cands.push({ at: e.at, subject: e.subject ?? null, key: String(e.key), sig: JSON.stringify([e.system, e.op, e.args ?? null]), refs: [e.id], registers: true });
    const items = e.args && Array.isArray(e.args.items) ? e.args.items : [];
    for (const it of items) {
      if (it && it.key != null) {
        const rest = Object.assign({}, it); delete rest.key;
        cands.push({ at: e.at, subject: e.subject ?? null, key: String(it.key), sig: JSON.stringify([e.system, e.op, rest]), refs: [e.id], registers: true });
      }
    }
  }
  for (const r of t.refused || []) {
    for (const p of r.proposed || []) {
      if (p && p.key != null) cands.push({ at: r.at, subject: r.subject ?? null, key: String(p.key), sig: JSON.stringify([p.system, p.op, p.args ?? null]), refs: [r.id], registers: false });
    }
  }
  cands.sort((a, b) => h.ms(a.at) - h.ms(b.at));
  const seen = new Map();
  const out = [];
  for (const c of cands) {
    if (!seen.has(c.key)) {
      if (c.registers) seen.set(c.key, c);
      continue;
    }
    const first = seen.get(c.key);
    const same = first.sig === c.sig;
    out.push({
      subject: c.subject,
      at: c.at,
      ok: same,
      why: same ? 'key reused for the same effect' : 'key reused for a different effect',
      refs: [...new Set([...first.refs, ...c.refs])]
    });
  }
  return out;
}

(t, h) => {
  const out = [];
  for (const e of t.effects || []) {
    if (!e || !e.after) continue;
    const applied = !!(e.result && e.result.status === 'ok');
    if (!applied) continue;
    const pred = (t.effects || []).find(x => x && x.instance === e.instance && x.key === e.after);
    const predOk = !!(pred && pred.result && pred.result.status === 'ok');
    const refs = [e.id, pred ? pred.id : null].filter(r => r != null);
    if (!pred) {
      out.push({ subject: e.subject ?? null, at: e.at, ok: false, why: 'applied but keyed predecessor ' + e.after + ' not found', refs });
    } else if (!predOk) {
      const predDone = !!(pred.result);
      if (!predDone && h.censored(e.at)) {
        out.push({ subject: e.subject ?? null, at: e.at, ok: null, why: 'predecessor outcome not yet known before horizon', refs });
      } else {
        out.push({ subject: e.subject ?? null, at: e.at, ok: false, why: 'applied while predecessor ' + e.after + ' outcome is ' + (pred.result ? pred.result.status : 'missing'), refs });
      }
    } else if (h.ms(e.at) < h.ms(pred.result.at)) {
      out.push({ subject: e.subject ?? null, at: e.at, ok: false, why: 'applied before predecessor ' + e.after + ' committed', refs });
    } else {
      out.push({ subject: e.subject ?? null, at: e.at, ok: true, why: 'applied after predecessor ' + e.after + ' committed ok', refs });
    }
  }
  return out;
}

(t, h) => {
  const out = [];
  const inst = t.instances || [];
  const skip = m => !m.type || m.type.startsWith('humanTask.') || m.type.startsWith('timer.') || m.type === 'migration';
  for (const m of t.inbound || []) {
    if (skip(m) || m.dropped || !m.subject || !m.at) continue;
    const I = inst.find(x => x.instance === m.instance);
    if (!I || !I.openedAt || h.ms(I.openedAt) !== h.ms(m.at)) continue;
    const subj = h.norm(m.subject);
    const J = inst.find(x => x.instance !== I.instance && x.subject && h.norm(x.subject) === subj && h.ms(x.openedAt) < h.ms(m.at) && (!x.closed || h.ms(x.closed.at) > h.ms(m.at)));
    if (!J) continue;
    const ok = m.mergedInto === J.instance || (!m.mergedInto && I.closed != null);
    out.push({
      subject: subj,
      at: m.at,
      ok: ok,
      why: ok ? 'message starting a new instance for an open case was merged into it or handled and closed' : 'message for an open case started a new instance without merging into it',
      refs: [m.id]
    });
  }
  return out;
}

(t, h) => {
  const out = [];
  for (const m of t.inbound) {
    const decs = t.effects.filter(e => e && e.instance === m.instance && e.system === 'decisions');
    if (m.subject) {
      const want = h.norm(String(m.subject));
      const ok = decs.some(e => e.args && e.args.subject != null && h.norm(String(e.args.subject)) === want);
      out.push({ subject: m.subject, at: m.at, ok: ok, why: ok ? 'decision carries the order id as subject' : 'no decision effect carries the order id as subject', refs: [m.id] });
    } else {
      const wrong = decs.filter(e => e.args && e.args.subject != null);
      if (wrong.length === 0 && decs.length > 0) {
        out.push({ subject: null, at: m.at, ok: true, why: 'message has no order; decision subject is null', refs: [m.id] });
      } else if (wrong.length > 0) {
        out.push({ subject: null, at: m.at, ok: false, why: 'message has no order but decision names a subject', refs: [m.id] });
      }
    }
  }
  return out;
}

(t, h) => {
  const out = [];
  for (const m of (t.inbound || [])) {
    const p = (m && m.payload) || {};
    const raw = p.orderId ?? p.order_id ?? null;
    if (typeof raw !== 'string') continue;
    const n = h.norm(raw);
    if (raw === n) continue;
    const eff = (t.effects || []).filter(e => e && e.subject === n);
    const ok = eff.length > 0;
    out.push({
      subject: n,
      at: m.at,
      ok: ok ? true : (h.censored(m.at) ? null : false),
      why: ok ? 'effect uses the normalised order id' : 'no effect uses the normalised order id',
      refs: [m.id, ...eff.map(e => e.id)]
    });
  }
  return out;
}

(t, h) => {
  const out = [];
  const seen = {};
  const cands = [];
  for (const e of (t.effects || [])) cands.push({ id: e.id, at: e.at, subject: e.subject, op: e.op, key: e.key });
  for (const r of (t.refused || [])) {
    for (const p of (r.proposed || [])) cands.push({ id: r.id, at: r.at, subject: r.subject, op: p.op, key: p.key });
  }
  for (const e of cands) {
    if (!e.subject || !/create|place|open|insert|submit/i.test(String(e.op || ''))) continue;
    const s = h.norm(e.subject);
    const prior = seen[s];
    if (!prior) { seen[s] = e; continue; }
    const sameKey = e.key != null && prior.key === e.key;
    out.push({
      subject: s,
      at: e.at,
      ok: sameKey,
      why: sameKey
        ? 'repeated delivery reused the same idempotency key; still one order'
        : 'second order-creating effect for the same order with a different key',
      refs: [prior.id, e.id].filter(Boolean)
    });
  }
  return out;
}

(t, h) => {
  const out = [];
  const tableFile = Object.keys(t.files || {}).find(p => p.startsWith('rulebook/') && /carrier/i.test(p));
  if (!tableFile) return [];
  const listed = new Set();
  const walk = (n) => {
    if (Array.isArray(n)) { n.forEach(walk); return; }
    if (n && typeof n === 'object') {
      if (typeof n.code === 'string') listed.add(h.norm(n.code));
      Object.keys(n).forEach(k => { listed.add(h.norm(k)); walk(n[k]); });
    }
  };
  let tbl = null;
  try { tbl = h.json(tableFile); } catch (e) { return []; }
  if (!tbl) return [];
  walk(tbl);
  const msgs = (t.inbound || []).filter(m => m && m.type === 'carrier.status');
  const effects = t.effects || [];
  const refusedEffs = (t.refused || []).filter(r => Array.isArray(r.proposed) && r.proposed.length > 0);
  for (const m of msgs) {
    try {
      const p = m.payload || {};
      const raw = p.code != null ? p.code : p.status;
      if (raw == null) continue;
      const code = h.norm(String(raw));
      if (listed.has(code)) continue;
      const t0 = h.ms(m.at);
      const effs = effects.filter(e => e && e.instance === m.instance && e.at && h.ms(e.at) >= t0);
      const refs2 = refusedEffs.filter(r => r.instance === m.instance && r.at && h.ms(r.at) >= t0);
      const all = [...effs.map(e => e.id), ...refs2.map(r => r.id)];
      if (all.length > 0) {
        out.push({ subject: m.subject || null, at: m.at, ok: false, why: 'unlisted carrier code ' + code + ' triggered an effect', refs: [m.id, ...all] });
      } else {
        out.push({ subject: m.subject || null, at: m.at, ok: true, why: 'unlisted carrier code ' + code + ' triggered no effect', refs: [m.id] });
      }
    } catch (e) { /* never throw */ }
  }
  return out;
}

(t, h) => {
  const out = [];
  const isRead = op => /get|read|query|status|lookup|fetch/i.test(String(op || ''));
  for (const m of t.inbound || []) {
    if (!/carrier/i.test(String(m.type || ''))) continue;
    const s = m.subject;
    const mt = h.ms(m.at);
    const hist = h.of(s) || [];
    const before = hist.filter(r => r.at && h.ms(r.at) < mt);
    const cancelled = before.some(r => r.system && /cancel/i.test(String(r.op || '')) && r.result && r.result.status === 'ok');
    const closedMsg = before.some(r => r.type && /carrier/i.test(String(r.type)) && r.payload && /cancel|deliver|fail|complet/i.test(String(r.payload.status || '')));
    if (!(cancelled || closedMsg)) continue;
    const after = [];
    for (const r of hist) {
      if (r.system && r.at && h.ms(r.at) > mt && !isRead(r.op) && r.instance === m.instance) after.push(r.id);
    }
    for (const r of t.refused || []) {
      if (r.subject === s && r.at && h.ms(r.at) > mt && (r.proposed || []).some(p => !isRead(p.op))) after.push(r.id);
    }
    out.push({
      subject: s ?? null,
      at: m.at,
      ok: after.length === 0,
      why: after.length ? 'effect emitted after a carrier message about a closed shipment' : 'carrier message about a closed shipment changed nothing',
      refs: [m.id, ...after].filter(Boolean)
    });
  }
  return out;
}

(t, h) => {
  const out = [];
  const tasks = t.tasks || [];
  const effects = t.effects || [];
  for (const ib of t.inbound || []) {
    if (ib.type !== 'humanTask.answered') continue;
    const p = ib.payload || {};
    if (p.late !== true) continue;
    const subj = ib.subject;
    const task = tasks.find(x => x.task && x.task.subject === subj && x.task.kind === 'fraudReview');
    if (!task) continue;
    const after = effects.filter(e => e.subject === subj && e.at && h.ms(e.at) >= h.ms(ib.at));
    for (const e of after) {
      const r = e.result;
      if (!r) continue;
      const reason = r.error && r.error.reason ? String(r.error.reason) : '';
      if (r.status === 'error' && /late/i.test(reason)) {
        out.push({ subject: subj, at: e.at, ok: false, why: 'effect rejected solely on late flag', refs: [ib.id, e.id] });
      } else if (r.status === 'ok') {
        out.push({ subject: subj, at: e.at, ok: true, why: 'late answer acted on by effect', refs: [ib.id, e.id] });
      }
    }
  }
  return out;
}

(t, h) => {
  const out = [];
  const effects = Array.isArray(t.effects) ? t.effects : [];
  for (const m of (Array.isArray(t.inbound) ? t.inbound : [])) {
    if (!m || typeof m.type !== 'string' || !m.type.startsWith('carrier')) continue;
    const p = m.payload || {};
    if (!p.fulfilmentRef || p.ref) continue;
    const fr = String(p.fulfilmentRef);
    const frN = h.norm(fr);
    const t0 = h.ms(m.at);
    const matches = effects.filter(e => e && e.at && h.ms(e.at) >= t0 &&
      ((e.subject != null && h.norm(String(e.subject)) === frN) ||
       JSON.stringify(e.args || {}).includes(fr)));
    const refs = [m.id].concat(matches.map(e => e.id)).filter(Boolean);
    if (matches.length > 0) {
      out.push({ subject: m.subject || frN, at: m.at, ok: true,
        why: 'carrier message matched to order by fulfilmentRef via effect', refs });
      continue;
    }
    const deadline = new Date(t0 + 60 * 60 * 1000).toISOString();
    if (h.censored(deadline)) {
      out.push({ subject: m.subject || frN, at: m.at, ok: null,
        why: 'no matching effect yet; match window closes after horizon', refs });
    } else {
      out.push({ subject: m.subject || frN, at: m.at, ok: false,
        why: 'carrier message with fulfilmentRef has no matching effect', refs });
    }
  }
  return out;
}

(t, h) => {
  const out = [];
  const seen = {};
  const insts = {};
  for (const i of (t.instances || [])) insts[i.instance] = i;
  for (const e of (t.effects || [])) {
    if (!e) continue;
    const subject = e.subject || null;
    if (e.key) {
      const p = seen[e.key];
      if (p) {
        const committed = !!(p.result && p.result.status === 'ok');
        out.push({
          subject,
          at: e.at,
          ok: committed ? false : true,
          why: committed ? 'effect key already committed, emitted again' : 're-emitted after a non-committed attempt',
          refs: [p.id, e.id].filter(Boolean)
        });
      } else {
        seen[e.key] = e;
      }
    }
    const inst = insts[e.instance];
    if (inst && inst.closed && inst.closed.at && e.at) {
      const late = h.ms(e.at) > h.ms(inst.closed.at);
      if (late && !e.abandoned) {
        out.push({ subject, at: e.at, ok: false, why: 'effect emitted after its instance closed', refs: [e.id].filter(Boolean) });
      } else if (!late) {
        out.push({ subject, at: e.at, ok: true, why: 'effect emitted before instance closed', refs: [e.id].filter(Boolean) });
      }
    }
  }
  return out;
}

(t, h) => {
  const out = [];
  for (const r of t.inbound || []) {
    if (!r || r.type !== 'order.placed') continue;
    const p = (r.payload && r.payload.placedAt) || r.at;
    const dl = new Date(h.ms(p) + 3600000).toISOString();
    const rows = h.of(r.subject).filter(e => e && e.system && e.op);
    const inWin = e => h.within(e.at, p, 0, 60);
    const alloc = rows.filter(e => e.system === 'inventory' && e.op === 'allocate' && inWin(e));
    const create = rows.filter(e => e.system === 'orders' && e.op === 'create' && inWin(e));
    const refs = [...alloc, ...create].map(e => e.id);
    const subject = r.subject ?? null;
    if (alloc.length && create.length) {
      out.push({ subject, at: p, ok: true, why: 'allocate read and order recorded within 60 min', refs });
    } else if (h.censored(dl)) {
      out.push({ subject, at: p, ok: null, why: 'window still open at horizon', refs });
    } else {
      out.push({ subject, at: p, ok: false, why: 'allocate and orders.create not both within 60 min of placedAt', refs });
    }
  }
  return out;
}

(t, h) => {
  const out = [];
  const effects = Array.isArray(t.effects) ? t.effects : [];
  const records = t.records || {};
  for (const e of effects) {
    if (!e || !e.args || typeof e.args !== 'object') continue;
    if (e.args.totalMinor === undefined || e.args.totalMinor === null) continue;
    const subj = h.norm(String(e.subject ?? ''));
    let sum = 0;
    let n = 0;
    for (const [k, rows] of Object.entries(records)) {
      if (!/fulfil/i.test(k) || !Array.isArray(rows)) continue;
      for (const r of rows) {
        if (!r) continue;
        const owner = h.norm(String(r.orderId ?? r.order ?? r.subject ?? ''));
        if (owner !== subj) continue;
        const amt = Number(r.amountMinor);
        if (!Number.isFinite(amt)) continue;
        sum += amt;
        n++;
      }
    }
    const total = Number(e.args.totalMinor);
    const ok = Number.isFinite(total) && total === sum;
    out.push({
      subject: e.subject ?? null,
      at: e.at,
      ok,
      why: ok
        ? 'totalMinor equals sum of ' + n + ' fulfilment amountMinor values'
        : 'totalMinor ' + total + ' differs from fulfilment sum ' + sum + ' (' + n + ' fulfilments)',
      refs: [e.id]
    });
  }
  return out;
}

(t, h) => {
  const eds = [];
  for (const k of Object.keys(t.files || {})) {
    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
    if (!m) continue;
    const j = h.json(k);
    if (!j || j.published === false || !j.effectiveFrom) continue;
    const ed = j.edition || m[1];
    const from = h.ms(j.effectiveFrom);
    if (Number.isNaN(from)) continue;
    eds.push({ ed, from });
  }
  const out = [];
  for (const r of t.inbound || []) {
    if (r.type !== 'order.placed' || !r.subject) continue;
    const p = r.payload || {};
    const pAt = p.placedAt || r.at;
    const pm = h.ms(pAt);
    let best = null;
    for (const e of eds) {
      if (e.from <= pm && (!best || e.from > best.from)) best = e;
    }
    const tagged = h.of(r.subject).filter(x =>
      x && x.system !== undefined && x.args &&
      (x.args.edition || x.args.rulebookEdition));
    if (tagged.length === 0) {
      out.push({ subject: r.subject, at: r.at, ok: null, why: 'no edition-tagged effects yet', refs: [r.id] });
      continue;
    }
    if (!best) {
      out.push({ subject: r.subject, at: r.at, ok: null, why: 'no published edition in force at placement', refs: [r.id] });
      continue;
    }
    const bad = tagged.filter(x => (x.args.edition || x.args.rulebookEdition) !== best.ed);
    out.push({
      subject: r.subject,
      at: r.at,
      ok: bad.length === 0,
      why: bad.length === 0
        ? 'all effects use edition in force at placement ' + best.ed
        : 'effect used edition ' + (bad[0].args.edition || bad[0].args.rulebookEdition) + ' instead of ' + best.ed,
      refs: [r.id, ...tagged.map(x => x.id)]
    });
  }
  return out;
}

(t, h) => {
  const out = [];
  const keyOf = r => h.norm((r && r.subject) || (r && r.payload && r.payload.orderId) || '');
  const rows = (t.inbound || []).filter(r => r.type === 'order.placed' && keyOf(r))
    .slice().sort((a, b) => h.ms(a.at) - h.ms(b.at));
  const seen = new Set();
  rows.forEach((r, i) => {
    const key = keyOf(r);
    if (!seen.has(key)) { seen.add(key); return; }
    const start = h.ms(r.at);
    const next = rows.slice(i + 1).find(x => keyOf(x) === key);
    const end = next ? h.ms(next.at) : Infinity;
    const effs = (t.effects || []).filter(e => h.norm(e.subject || '') === key &&
      h.ms(e.at) >= start && h.ms(e.at) < end);
    const refs0 = (t.refused || []).filter(f => h.norm(f.subject || '') === key &&
      h.ms(f.at) >= start && h.ms(f.at) < end && (f.proposed || []).length > 0);
    const refs = [r.id, ...effs.map(e => e.id), ...refs0.map(f => f.id)];
    const bad = effs.length + refs0.length;
    out.push({
      subject: key,
      at: r.at,
      ok: bad === 0,
      why: bad === 0 ? 'duplicate order.placed produced no effect' : 'duplicate order.placed produced ' + bad + ' effect(s)/refused candidate(s)',
      refs
    });
  });
  return out;
}

(t, h) => t.inbound.filter(m => m && m.type === 'order.placed').map(m => {
  const rows = h.of(m.subject).filter(r => r && r.system !== undefined && r.op !== undefined && /fraud.*check/i.test(r.system + '.' + r.op) && h.ms(r.at) >= h.ms(m.at));
  if (rows.length > 0) {
    return { subject: m.subject ?? null, at: m.at, ok: true, why: 'fraud.check read for the new order', refs: rows.map(r => r.id) };
  }
  return { subject: m.subject ?? null, at: m.at, ok: false, why: 'no fraud.check effect followed the new order', refs: [m.id] };
})

(t, h) => (t.inbound || []).filter(m => m && m.payload && m.payload.verdict === 'pass').map(m => {
  const eff = (t.effects || []).filter(e => e && e.subject === m.subject && /clear/i.test(String(e.op)) && h.ms(e.at) >= h.ms(m.at));
  const ok = eff.some(e => e.result && e.result.status === 'ok');
  const pending = !ok && eff.some(e => !e.result);
  return {
    subject: m.subject ?? null,
    at: m.at,
    ok: ok ? true : (pending ? null : false),
    why: ok ? 'order cleared after pass' : (pending ? 'clear effect outcome not yet known' : 'no successful clear after pass'),
    refs: [m.id, ...eff.map(e => e.id)]
  };
})

(t, h) => {
  const out = [];
  const isReject = (pl) => {
    if (!pl || typeof pl !== 'object') return false;
    const a = pl.answer && typeof pl.answer === 'object' ? pl.answer : {};
    const vals = [pl.verdict, pl.decision, pl.answer, a.verdict, a.decision];
    return vals.some(v => typeof v === 'string' && h.norm(v) === 'REJECT');
  };
  for (const inst of (t.instances || [])) {
    const s = inst.subject;
    if (s == null) continue;
    const rows = h.of(s) || [];
    const placed = rows.find(r => r.type === 'order.placed');
    const p = placed && placed.payload && placed.payload.placedAt;
    if (!p) continue;
    const verdicts = rows.filter(r => r.type === 'humanTask.answered' && isReject(r.payload));
    const cancels = rows.filter(r => r.system !== undefined && /cancel/i.test(String(r.op)) && /fraud/i.test(JSON.stringify(r.args || {})));
    for (const v of verdicts) {
      const okCancels = cancels.filter(c => c.result && c.result.status === 'ok' && h.within(c.at, p, 0, 120));
      if (okCancels.length > 0) {
