    const subj = m.subject == null ? null : h.norm(m.subject);
    const effs = (t.effects || []).filter(e =>
      e && match.test(String(e.op || '')) &&
      (subj === null || (e.subject != null && h.norm(e.subject) === subj)) &&
      h.ms(e.at) >= h.ms(m.at));
    const done = effs.find(e => e.result && e.result.status === 'ok');
    if (done) {
      out.push({ subject: subj, at: m.at, ok: true, why: 'completed compensating effect after ' + m.type, refs: [m.id, done.id] });
    } else if (effs.some(e => !e.result)) {
      out.push({ subject: subj, at: m.at, ok: null, why: 'compensating effect still pending', refs: [m.id] });
    } else if (h.minutes(m.at, t.horizon) < 1440) {
      out.push({ subject: subj, at: m.at, ok: null, why: 'too recent to decide before horizon', refs: [m.id] });
    } else {
      out.push({ subject: subj, at: m.at, ok: false, why: 'no completed refund/release/cancel effect after ' + m.type, refs: [m.id] });
    }
  }
  return out;
}

(t, h) => {
  const cands = [];
  for (const e of (t.effects || [])) {
    if (e && e.args && e.args.status != null) cands.push({ e, at: e.at, ref: e.id });
  }
  for (const r of (t.refused || [])) {
    for (const p of (r.proposed || [])) {
      if (p && p.args && p.args.status != null) {
        cands.push({ e: { ...p, subject: p.subject != null ? p.subject : r.subject, instance: r.instance }, at: r.at, ref: r.id });
      }
    }
  }
  cands.sort((a, b) => h.ms(a.at) - h.ms(b.at));
  const seen = new Map();
  const out = [];
  for (const c of cands) {
    const e = c.e;
    const subj = e.subject != null ? e.subject : null;
    const target = (e.args && (e.args.orderId || e.args.fulfilmentId || e.args.fulfillmentId || e.args.id)) || subj;
    const status = String(e.args.status);
    const key = [e.system || '', e.op || '', target || '', status].join('|');
    const isRepeat = seen.has(key);
    if (!isRepeat) seen.set(key, c.ref);
    out.push({
      subject: subj,
      at: c.at,
      ok: !isRepeat,
      why: isRepeat ? ('status ' + status + ' set again on ' + target + ' (first by ' + seen.get(key) + ')') : ('status ' + status + ' set once on ' + target),
      refs: [c.ref]
    });
  }
  return out;
}

(t, h) => {
  const raw = h.json('master/customers.json');
  const list = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.rows) ? raw.rows : Object.values(raw || {}).filter(v => v && typeof v === 'object'));
  const norm = v => (v == null ? '' : String(v).trim().toLowerCase());
  const out = [];
  for (const e of (t.effects || [])) {
    if (!e) continue;
    const sys = String(e.system || '');
    const op = String(e.op || '');
    if (!/mail|notif|sms|message/i.test(sys) && !/send|notify|email/i.test(op)) continue;
    const to = e.args ? e.args.to : undefined;
    const subj = e.subject ?? null;
    const row = subj == null ? undefined : list.find(r => r && [r.id, r.customerId, r.subject, r.key].some(v => v != null && h.norm(String(v)) === h.norm(String(subj))));
    if (!row) {
      out.push({ subject: subj, at: e.at, ok: null, why: 'no customer record for subject', refs: [e.id] });
      continue;
    }
    const want = norm(row.email);
    if (!want) {
      out.push({ subject: subj, at: e.at, ok: null, why: 'customer has no email on file', refs: [e.id] });
      continue;
    }
    const ok = norm(to) === want;
    out.push({ subject: subj, at: e.at, ok, why: ok ? 'notification addressed to customer email' : 'notification to ' + String(to) + ' differs from customer email', refs: [e.id] });
  }
  return out;
}

(t, h) => t.effects.filter(e => /amend/i.test(e.op || '')).flatMap(e => {
  const prior = h.of(e.subject).some(r => r.type === 'fulfilment.unavailable' && h.ms(r.at) <= h.ms(e.at));
  if (prior) return [];
  const changed = !!(e.result && e.result.status === 'ok');
  return [{
    subject: e.subject ?? null,
    at: e.at,
    ok: !changed,
    why: changed ? 'amend applied with no unavailable fulfilment' : 'amend with no unavailable fulfilment changed nothing',
    refs: [e.id]
  }];
})

(t, h) => {
  const out = [];
  const isCancel = (op) => /cancel/i.test(String((op && op.name) || op || ''));
  const isWhole = (args) => !args || (!args.fulfilmentId && !args.fulfilmentIds && args.scope !== 'fulfilment' && args.scope !== 'partial');
  const sameSubj = (a, b) => a != null && b != null && h.norm(a) === h.norm(b);
  const collected = (subject, at) => {
    if (subject == null) return false;
    const inb = (t.inbound || []).some(m => sameSubj(m.subject, subject) && /collect/i.test(String(m.type || '')) && m.at && h.ms(m.at) < h.ms(at));
    const eff = (t.effects || []).some(e => sameSubj(e.subject, subject) && /collect/i.test(String(e.op || '')) && e.result && e.result.status === 'ok' && e.at && h.ms(e.at) < h.ms(at));
    return inb || eff;
  };
  const check = (c, subject, at, refs) => {
    if (!c || !isCancel(c.op) || !isWhole(c.args) || !at) return;
    const bad = collected(subject, at);
    out.push({
      subject: subject == null ? null : subject,
      at,
      ok: !bad,
      why: bad ? 'whole-order cancel emitted after a fulfilment was collected' : 'whole-order cancel emitted before any collection',
      refs
    });
  };
  for (const e of (t.effects || [])) check(e, e.subject, e.at, [e.id]);
  for (const r of (t.refused || [])) {
    for (const p of (r.proposed || [])) check(p, r.subject, r.at, [r.id]);
  }
  return out;
}
